import test from 'node:test';
import assert from 'node:assert/strict';
import { exportCsv } from '../src/export.js';

test('exportCsv returns CSV string with header', () => {
  const csv = exportCsv([]);
  assert.ok(csv.startsWith('number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due\n'));
});

test('exportCsv returns empty array as just header', () => {
  const csv = exportCsv([]);
  assert.equal(csv, 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due\n');
});

test('exportCsv exports single invoice', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
    },
  ];
  const csv = exportCsv(invoices);
  const lines = csv.split('\n');
  assert.equal(lines.length, 3); // header, data, empty line at end
  assert.equal(lines[1], 'INV-2026-0001,Acme Inc,2026-10-01,2026-10-31,issued,10.00,0.00,0.00,10.00,10.00');
});

test('exportCsv includes customer name from lookup', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'C-001',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 0 }],
    },
  ];
  const csv = exportCsv(invoices);
  assert.ok(csv.includes('Acme Inc'));
});

test('exportCsv quotes customer name with comma', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'C-002',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 0 }],
    },
  ];
  const csv = exportCsv(invoices);
  assert.ok(csv.includes('"Beta, Inc"'));
});

test('exportCsv doubles quotes in customer name', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'C-003',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 0 }],
    },
  ];
  const csv = exportCsv(invoices);
  assert.ok(csv.includes('"Kite & Co"'));
});

test('exportCsv formats amounts with 2 decimals', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'C-001',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 12345, discountPercent: 0, vatRate: 0 }],
    },
  ];
  const csv = exportCsv(invoices);
  assert.ok(csv.includes('123.45'));
});

test('exportCsv formats zero amounts correctly', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'C-001',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 0, discountPercent: 0, vatRate: 0 }],
    },
  ];
  const csv = exportCsv(invoices);
  assert.ok(csv.includes('0.00'));
});

test('exportCsv does not use thousands separator', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'C-001',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 1234567, discountPercent: 0, vatRate: 0 }],
    },
  ];
  const csv = exportCsv(invoices);
  assert.ok(csv.includes('12345.67'));
  assert.ok(!csv.includes('12,345'));
});

test('exportCsv does not use currency sign', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'C-001',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 0 }],
    },
  ];
  const csv = exportCsv(invoices);
  assert.ok(!csv.includes('€'));
});

test('exportCsv includes discount in output', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'C-001',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 1000, discountPercent: 10, vatRate: 0 }],
    },
  ];
  const csv = exportCsv(invoices);
  assert.ok(csv.includes('100.00')); // discount
});

test('exportCsv includes VAT in output', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'C-001',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 20 }],
    },
  ];
  const csv = exportCsv(invoices);
  assert.ok(csv.includes('200.00')); // vat
});

test('exportCsv calculates due as balance due', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'C-001',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'partially_paid',
      lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
      payments: [{ amount: 400, date: '2026-10-05' }],
    },
  ];
  const csv = exportCsv(invoices);
  assert.ok(csv.includes('6.00')); // due: 10.00 - 4.00
});

test('exportCsv exports multiple invoices', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'C-001',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 0 }],
    },
    {
      number: 'INV-002',
      customerId: 'C-001',
      issueDate: '2026-10-05',
      dueDate: '2026-11-04',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 200, discountPercent: 0, vatRate: 0 }],
    },
  ];
  const csv = exportCsv(invoices);
  const lines = csv.split('\n');
  assert.equal(lines.length, 4); // header, 2 data, empty line
  assert.ok(lines[1].includes('INV-001'));
  assert.ok(lines[2].includes('INV-002'));
});

test('exportCsv preserves invoice order', () => {
  const invoices = [
    {
      number: 'INV-003',
      customerId: 'C-001',
      issueDate: '2026-10-03',
      dueDate: '2026-10-31',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 0 }],
    },
    {
      number: 'INV-001',
      customerId: 'C-001',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 0 }],
    },
  ];
  const csv = exportCsv(invoices);
  const lines = csv.split('\n');
  assert.ok(lines[1].includes('INV-003'));
  assert.ok(lines[2].includes('INV-001'));
});

test('exportCsv handles draft status', () => {
  const invoices = [
    {
      number: '',
      customerId: 'C-001',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'draft',
      lines: [{ qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 0 }],
    },
  ];
  const csv = exportCsv(invoices);
  assert.ok(csv.includes('draft'));
});

test('exportCsv handles missing invoice number', () => {
  const invoices = [
    {
      customerId: 'C-001',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'draft',
      lines: [{ qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 0 }],
    },
  ];
  const csv = exportCsv(invoices);
  const lines = csv.split('\n');
  assert.ok(lines[1].startsWith(','));
});

test('exportCsv ends each line with newline', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'C-001',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 0 }],
    },
  ];
  const csv = exportCsv(invoices);
  assert.ok(csv.endsWith('\n'));
});

test('exportCsv with complex invoice', () => {
  const invoices = [
    {
      number: 'INV-2026-0042',
      customerId: 'C-002',
      issueDate: '2026-10-05',
      dueDate: '2026-11-04',
      status: 'partially_paid',
      lines: [
        { qty: 2, unitPrice: 5000, discountPercent: 10, vatRate: 20 },
        { qty: 1, unitPrice: 3000, discountPercent: 5, vatRate: 9 },
      ],
      payments: [{ amount: 5000, date: '2026-10-10' }],
    },
  ];
  const csv = exportCsv(invoices);
  assert.ok(csv.includes('INV-2026-0042'));
  assert.ok(csv.includes('"Beta, Inc"'));
  assert.ok(csv.includes('partially_paid'));
  const lines = csv.split('\n');
  assert.equal(lines.length, 3);
});

test('exportCsv calculates totals correctly', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'C-001',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 1000, discountPercent: 10, vatRate: 20 }],
    },
  ];
  const csv = exportCsv(invoices);
  // subtotal: 1000 = 10.00
  // discount: 100 = 1.00
  // vat: (1000 - 100) * 0.20 = 180 = 1.80
  // total: 10.00 - 1.00 + 1.80 = 10.80
  assert.ok(csv.includes('10.00,1.00,1.80,10.80'));
});

test('exportCsv handles very large amounts', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'C-001',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'issued',
      lines: [{ qty: 1000, unitPrice: 100000, discountPercent: 0, vatRate: 0 }],
    },
  ];
  const csv = exportCsv(invoices);
  assert.ok(csv.includes('1000000.00'));
});

test('exportCsv header contains all required columns', () => {
  const csv = exportCsv([]);
  const header = csv.split('\n')[0];
  assert.equal(header, 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
});

test('exportCsv escapes quotes in customer name correctly', () => {
  // C-004 has a customer with quotes in name
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'C-004',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 0 }],
    },
  ];
  const csv = exportCsv(invoices);
  // Customer C-004 has name "Design, Inc" with quotes (if it exists in data)
  // Should be properly escaped
  const lines = csv.split('\n');
  assert.ok(lines[1]); // Just verify row exists
});

test('exportCsv with paid invoice has zero due', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'C-001',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'paid',
      lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
      payments: [{ amount: 1000, date: '2026-10-15' }],
    },
  ];
  const csv = exportCsv(invoices);
  assert.ok(csv.includes('10.00,0.00,0.00,10.00,0.00'));
});

