test('exportCsv with complex invoice', () => {
  const invoices = [
    {
      number: 'INV-2026-0042',
      customerId: 'C-002',
      issueDate: '2026-10-05',
      dueDate: '2026-11-04',
      status: 'partially_paid',
      lines: [
        { qty: 2, unitPrice: 5000, discountPercent: 10, vatRate: 20 },
        { qty: 1, unitPrice: 3000, discountPercent: 5, vatRate: 9 },
      ],
      payments: [{ amount: 5000, date: '2026-10-10' }],
    },
