test('exportCsv calculates totals correctly', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'C-001',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 1000, discountPercent: 10, vatRate: 20 }],
    },
  ];
  const csv = exportCsv(invoices);
  // subtotal: 1000 = 10.00
  // discount: 100 = 1.00
  // vat: (1000 - 100) * 0.20 = 180 = 1.80
  // total: 10.00 - 1.00 + 1.80 = 10.80
  assert.ok(csv.includes('10.00,1.00,1.80,10.80'));
});

